#nullable enable // autogenerated

using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2Logic.Models.Widgets
{
    [RequireComponent(typeof(Image))]
    [ExecuteAlways]
    public class AnimationImageSetter : MonoBehaviour
    {
        private void OnEnable()
        {
            SetSpriteIndex(index);
        }
        private void LateUpdate()
        {
            if (sprites != null && sprites.Length > 0)
            {
                if (index != beforeIndex)
                {
                    SetSpriteIndex(index);
                }
            }
        }

        public void SetSpritePercent(float percent)
        {
            if (sprites == null)
                return;
            SetSpriteIndex(Mathf.FloorToInt(percent * sprites.Length));
        }

        public void SetSpriteIndex(int i)
        {
            if (sprites == null)
                return;
            index = Mathf.Clamp(i, 0, sprites.Length - 1);
            beforeIndex = index;
            Sprite sprite = sprites[index];
            if (Global.Resources != null)
            {
                sprite = Global.Resources.GetFinalSprite(sprite);
            }
            Renderer.sprite = sprite;
        }
        private Image Renderer
        {
            get
            {
                if (!image.Exists())
                {
                    image = GetComponent<Image>();
                }
                return image;
            }
        }
        private Image? image;
        public Sprite[]? sprites;
        private int beforeIndex = -1;
        [SerializeField]
        private int index = 0;
    }
}